// SPDX-License-Identifier: MIT
pragma solidity 0.8.34;

/// @title IProofSystem
/// @notice Interface for proof-verifying systems referenced from a per-rollup `IRollupContract`
///         contract's vkey map.
/// @dev A proof system is any contract that can check `(proof, publicInputsHash)` — ZK, ECDSA,
///      etc. There is no central registry; each rollup owner is responsible for vetting which
///      proof system addresses are added to their rollup's allowed set.
interface IProofSystem {
    /// @notice Verifies a proof against a single public input hash
    /// @param proof The proof bytes (interpretation is proof-system-specific)
    /// @param publicInputsHash Hash of all public inputs for the proof
    /// @return valid True if the proof is valid, false otherwise
    function verify(bytes calldata proof, bytes32 publicInputsHash) external view returns (bool valid);
}

../eez-core-protocol/src/interfaces/IRol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.34;

/// @title IRollupContract
/// @notice Per-rollup contract interface — the canonical (or custom) handle that owns proof
///         system membership, vkeys, threshold, and ownership for ONE rollup. Held by the
///         central EEZ registry as `rollups[rid].rollupContract` and queried by the registry
///         during postAndVerifyBatch + root escape paths.
/// @dev The central EEZ contract holds the source of truth for root, ether balance,
///      the deferred queue, and the proxy registry. Everything that mutates a rollup's PS
///      group / threshold / owner happens on this contract; the only call back into the
///      central registry is `setRoot` (the owner escape hatch), which `EEZ` allows
///      because `msg.sender` equals the registered `rollupContract`.
interface IRollupContract {
    /// @notice Notification fired by `EEZ` when this contract becomes the registered manager
    ///         for a rollup via `EEZ.registerRollup`. The implementation MUST accept calls
    ///         only from the central `EEZ` registry and MUST authorize `registrant` under its
    ///         registration policy before accepting the initial state. The reference Rollup
    ///         requires `registrant` to be its current owner.
    /// @dev The rollupId is stored so that subsequent calls from this contract back into the
    ///      registry (`EEZ.setRoot(rid, root)`) can pass the id explicitly — the
    ///      registry has no reverse-lookup mapping from contract address to rollupId.
    /// @param rollupId Id the registry assigned to this rollup.
    /// @param registrant Original caller of `EEZ.registerRollup`, forwarded by the registry.
    function rollupContractRegistered(uint64 rollupId, address registrant) external;

    /// @notice Bulk vkey lookup used by `EEZ.postAndVerifyBatch` for the
    ///         subset of proof systems this rollup chose for the batch.
    /// @dev Strict semantic: every `proofSystems[i]` MUST be allowed for this rollup. The
    ///      implementation MUST revert if any input is not allowed, and MUST revert if
    ///      `proofSystems.length` is below the manager's threshold. On success, every entry
    ///      of the returned `vkeys` is non-zero. The registry consumes the result verbatim;
    ///      successful return means both threshold and per-PS membership are satisfied.
    /// @param proofSystems Proof-system subset selected for this rollup, in strictly increasing address order.
    /// @return vkeys Nonzero verification keys corresponding to proofSystems in input order.
    function checkProofSystemsAndGetVkeys(address[] calldata proofSystems)
        external
        view
        returns (bytes32[] memory vkeys);

    /// @notice Returns the opaque `customData` blob this rollup binds into its per-rollup
    ///         verification commit during proof verification. Folded one rollup at a time
    ///         into the batch's SHARED public input inside `_verifyProofSystemBatch`.
    ///         `blockNumber` is the single L1 block the whole batch is bound to, passed in via
    ///         `EEZ.postAndVerifyBatch`.
    /// @dev The contents are entirely rollup-defined — e.g. an ABI-encoded `(timestamp,
    ///      blockHash)` pair, or any other L1-view commitment the rollup's circuit expects.
    ///      `blockNumber == 0` conventionally keeps a no-context behavior (empty blob). A
    ///      non-zero `blockNumber` binds the rollup's chosen view; implementations SHOULD
    ///      reject a blockNumber they cannot resolve so a stale value can't silently bind an
    ///      empty blob into the proof commit.
    /// @param blockNumber L1 block context requested by the batch, interpreted by the rollup manager.
    /// @return customData Rollup-defined context bytes committed into the shared public input.
    function getCustomData(uint64 blockNumber) external view returns (bytes memory customData);
}
